def get_permission(
    ContentType,
    Permission,
    app_label,
    model_name,
    codename,
    permission_name,
):
    content_type, created = ContentType.objects.get_or_create(
        app_label=app_label,
        model=model_name,
    )

    permission, created = Permission.objects.get_or_create(
        content_type=content_type,
        codename=codename,
        defaults={
            'name': permission_name,
        },
    )

    return permission


